typedef unsigned int uint32;

class color32
{
public:
	uint32 i;
	color32(uint32 ic=0) : i(ic) {}
};

class stringx
{
	char *s;
public:
	stringx(const stringx&);
	~stringx();
};

class FEMenu;
class FEMenuSystem;

class FEMenuEntry
{
public:
	FEMenuEntry(stringx l, FEMenu* m, bool floating=false, void* ft=0);
};

enum {
	FEMENU_WRAP = 0x002,
	FEMENU_DONT_SHOW_DISABLED = 0x400,
};

class FEMenu
{
public:
	int center_x;
	int center_y;
	int num_entries;
	int dy;
	int half;
	int menu_num;
	bool init;
	stringx font_filename;
	color32 color;
	color32 color_high;
	color32 color_high_alt;
	float scale;
	float scale_high;
	int max_vis_entries;
	int flags;
	FEMenuEntry* entries;
	FEMenuEntry* first_vis_entry;
	FEMenuEntry* last_vis_entry;
	FEMenuEntry* highlighted;
	FEMenuSystem* system;
	FEMenu* back;
	int back_num;
	FEMenu *submenus;
	FEMenu *active;
	FEMenu *parent;
	void *helpText;
	int helpFlags;
	FEMenu* next_sub;

	FEMenu();
	virtual ~FEMenu();
	virtual void setBack(FEMenu*, int=1);
	virtual void setHigh(FEMenuEntry*, bool=true);
	virtual void setVis(FEMenuEntry*);
	virtual void Add(FEMenuEntry*);
	virtual void Init();
	virtual void Load(bool);
	virtual void Load();
	virtual void Draw();
	virtual void DrawTop();
	virtual void UpdateInScene();
	virtual void Update(float);
	virtual void HighlightDefault();
	virtual void OnActivate();
	virtual void OnActivate(int);
	virtual void OnUnactivate(FEMenu*);
	virtual void OnSelect(int);
	virtual void OnStart(int);
	virtual void OnUp(int);
	virtual void OnDown(int);
	virtual void OnLeft(int);
	virtual void OnRight(int);
	virtual void OnCross(int);
	virtual void OnTriangle(int);
	virtual void OnSquare(int);
	virtual void OnCircle(int);
	virtual void OnL1(int);
	virtual void OnR1(int);
	virtual void OnL2(int);
	virtual void OnR2(int);
	virtual void OnAnyButtonPress(int, int);
	virtual void OnButtonRelease(int, int);
	virtual void SetAllScale(float);
	virtual void MakeActive(FEMenu*);
	virtual void SetHelpText(int);
	virtual void Select(int);
protected:
	virtual void cons(FEMenuSystem*, int, int, int=8);
	virtual void cons(FEMenuSystem*, int, int, color32, color32, int=8);
	virtual void cons(FEMenuSystem*, int, int, color32, color32, color32, float=1.0f, float=1.2f, int=8, int=0);
	virtual void Next();
	virtual void Previous();
	virtual void Select();
	virtual void AddSubmenu(FEMenu*);
};

class PauseMenuSystem;

class TimeAttackPauseMenuClass : public FEMenu
{
public:
	PauseMenuSystem* sys;
	FEMenuEntry *options;
	FEMenuEntry *trickbook;

	TimeAttackPauseMenuClass(FEMenuSystem* m, int x, int y, color32 c, color32 ch, color32 cha);
};

extern stringx ksGlobalTextArray[];

enum {
	GT_MENU_OPTIONS = 0,
	GT_MENU_TRICKBOOK = 7,
	GT_MENU_BEACH_SELECT = 14,
	GT_MENU_CONTINUE = 17,
	GT_MENU_RESTART_MATCH = 23,
	GT_MENU_END_RUN = 26,
	GT_FE_MENU_RETURN_FE = 280,
};

#define NEW new

TimeAttackPauseMenuClass::TimeAttackPauseMenuClass(FEMenuSystem* m, int x, int y, color32 c, color32 ch, color32 cha)
{
	FEMenu::cons(m, x, y, c, ch, cha);
	sys = (PauseMenuSystem*) m;

	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_CONTINUE], this));
	options = NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_OPTIONS], this);
	Add(options);
	trickbook = NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_TRICKBOOK], this);
	Add(trickbook);
	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_END_RUN], this));
	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_RESTART_MATCH], this));
	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_BEACH_SELECT], this));
	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_FE_MENU_RETURN_FE], this));

	scale_high = 1.0f;
	flags |= FEMENU_WRAP | FEMENU_DONT_SHOW_DISABLED;
}
